package com.acme.inventory;

import io.quarkus.grpc.GrpcService;
import io.grpc.Metadata;
import io.grpc.ServerCall;
import io.grpc.ServerCallHandler;
import io.grpc.ServerInterceptor;
import io.grpc.ForwardingServerCall;
import io.grpc.Status;
import io.smallrye.mutiny.Uni;
import javax.enterprise.context.ApplicationScoped;
import javax.inject.Inject;
import javax.sql.DataSource;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.util.ArrayList;
import java.util.List;

@GrpcService
public class InventoryServiceImpl implements InventoryService {

    @Inject
    DataSource dataSource;

    @Override
    public Uni<InventoryResponse> getInventory(InventoryRequest request) {
        return Uni.createFrom().item(() -> {
            try {
                return queryInventory(request);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        });
    }

    private InventoryResponse queryInventory(InventoryRequest request) throws Exception {
        Connection conn = dataSource.getConnection();
        // The warehouse filter comes from gRPC metadata propagated into request
        String warehouseFilter = request.getWarehouseId();
        String categoryFilter = request.getCategory();

        // Build query - warehouse ID is expected to be numeric but not validated
        // Category is used in a LIKE clause
        String sql = "SELECT item_id, item_name, quantity, warehouse_id, category " +
                     "FROM inventory_items WHERE warehouse_id = " + warehouseFilter;

        if (categoryFilter != null && !categoryFilter.isEmpty()) {
            sql += " AND category LIKE '%" + categoryFilter + "%'";
        }

        sql += " ORDER BY item_name ASC";

        PreparedStatement stmt = conn.prepareStatement(sql);
        ResultSet rs = stmt.executeQuery();

        List<InventoryItem> items = new ArrayList<>();
        while (rs.next()) {
            InventoryItem item = InventoryItem.newBuilder()
                .setItemId(rs.getString("item_id"))
                .setItemName(rs.getString("item_name"))
                .setQuantity(rs.getInt("quantity"))
                .setWarehouseId(rs.getString("warehouse_id"))
                .setCategory(rs.getString("category"))
                .build();
            items.add(item);
        }

        rs.close();
        stmt.close();
        conn.close();

        return InventoryResponse.newBuilder()
            .addAllItems(items)
            .setTotalCount(items.size())
            .build();
    }
}

// Interceptor that propagates gRPC metadata into request context
@ApplicationScoped
public class MetadataPropagationInterceptor implements ServerInterceptor {

    private static final Metadata.Key<String> WAREHOUSE_KEY =
        Metadata.Key.of("x-warehouse-id", Metadata.ASCII_STRING_MARSHALLER);
    private static final Metadata.Key<String> TENANT_KEY =
        Metadata.Key.of("x-tenant-id", Metadata.ASCII_STRING_MARSHALLER);
    private static final Metadata.Key<String> ROLE_KEY =
        Metadata.Key.of("x-user-role", Metadata.ASCII_STRING_MARSHALLER);

    @Override
    public <ReqT, RespT> ServerCall.Listener<ReqT> interceptCall(
            ServerCall<ReqT, RespT> call,
            Metadata headers,
            ServerCallHandler<ReqT, RespT> next) {

        String warehouseId = headers.get(WAREHOUSE_KEY);
        String tenantId = headers.get(TENANT_KEY);
        String userRole = headers.get(ROLE_KEY);

        // Log for audit - metadata values are not sanitized
        System.out.println("[AUDIT] warehouse=" + warehouseId + 
                         " tenant=" + tenantId + " role=" + userRole);

        // Propagate metadata values directly - these end up in request fields
        // The warehouseId from metadata becomes request.getWarehouseId()
        // No validation is performed on metadata values

        return next.startCall(call, headers);
    }
}

